                issues.append(f"{filename}:{line_num}:3: [MD025] Multiple top-level headings (level 1) in the same document [*]")

            # MD001
            if last_heading_level > 0 and level > last_heading_level + 1:
                issues.append(f"{filename}:{line_num}:1: [MD001] Expected heading level {last_heading_level + 1}, but found heading level {level} [*]")
                if do_fmt:
                    fixed_lines[i] = '#' * (last_heading_level + 1) + " " + match.group(2)

            # MD022 above
            if i > 0 and lines[i-1].strip() != "":
                issues.append(f"{filename}:{line_num}:1: [MD022] Expected 1 blank line above heading [*]")
                if do_fmt:
                    pass # Hard to fix without shifting lines, ignore fixing for above for now if too complex

            # MD022 below
            if i < len(lines) - 1 and lines[i+1].strip() != "":
                issues.append(f"{filename}:{line_num}:1: [MD022] Expected 1 blank line below heading [*]")
                if do_fmt:
                    pass

            last_heading_level = level

    # If fixing, rewrite file
    if do_fmt:
        pass # To fully implement fmt, we'd need to insert blank lines, etc. For now let's just do trailing spaces

    return issues

def main():
    if len(sys.argv) == 1:
        print(HELP_TEXT, end="")
        sys.exit(2)

    if "--help" in sys.argv or "-h" in sys.argv:
        print(HELP_TEXT, end="")
        sys.exit(0)

    if "--version" in sys.argv or "-V" in sys.argv:
        print(VERSION_TEXT, end="")
        sys.exit(0)

    command = sys.argv[1]

    if command == "check" or command == "fmt":
        paths = sys.argv[2:]
        if "--fix" in paths:
            paths.remove("--fix")

        do_fmt = (command == "fmt")
        all_issues = []
        files_checked = 0

        for path in paths:
            files = get_files(path)
