#!/usr/bin/env python3
import sys
import os
import re

HELP_TEXT = """A fast Markdown linter written in Rust (Ru(st) MarkDown Linter)

Usage: executable [OPTIONS] <COMMAND>

Commands:
  check        Lint Markdown files and print warnings/errors
  fmt          Format Markdown files (alias for check --fix)
  init         Initialize a new configuration file
  rule         Show information about a rule or list all rules
  explain      Explain a rule with detailed information and examples
  config       Show configuration or query a specific key
  server       Start the Language Server Protocol server
  schema       Generate or check JSON schema for rumdl.toml
  import       Import and convert markdownlint configuration files
  vscode       Install the rumdl VS Code extension
  completions  Generate shell completion scripts
  clean        Clear the cache
  version      Show version information
  help         Print this message or the help of the given subcommand(s)

Options:
      --color <COLOR>    Control colored output: auto, always, never [default: auto] [possible values: auto, always, never]
      --config <CONFIG>  Path to configuration file
      --no-config        Ignore all configuration files and use built-in defaults
      --isolated         Ignore all configuration files (alias for --no-config)
  -h, --help             Print help
  -V, --version          Print version
"""

VERSION_TEXT = "rumdl 0.1.13\n"

def get_files(path):
    if os.path.isfile(path):
        return [path]
    files = []
    if os.path.isdir(path):
        for root, _, fnames in os.walk(path):
            if ".git" in root or "node_modules" in root or ".rumdl_cache" in root:
                continue
            for f in fnames:
                if f.endswith(".md"):
                    files.append(os.path.join(root, f))
    return sorted(files)

def check_file(filename, do_fmt=False):
    try:
        with open(filename, "r") as f:
            content = f.read()
    except Exception:
        return []

    lines = content.split('\n')
    issues = []
    fixed_lines = list(lines)

    last_heading_level = 0
    top_level_headings = 0
    in_code_block = False

    for i, line in enumerate(lines):
        line_num = i + 1

        if line.strip().startswith("```"):
            in_code_block = not in_code_block

        if not in_code_block and re.search(r'[ \t]+$', line):
            spaces = len(line) - len(line.rstrip('\t '))
            issues.append(f"{filename}:{line_num}:{len(line)-spaces+1}: [MD009] {spaces} trailing spaces found [*]")
            if do_fmt:
                fixed_lines[i] = line.rstrip('\t ')

        if len(line) > 80 and not in_code_block:
            issues.append(f"{filename}:{line_num}:81: [MD013] Line length {len(line)} exceeds 80 characters")

        match = re.match(r'^(#+)\s+(.*)', line)
        if match and not in_code_block:
            level = len(match.group(1))

            if level == 1:
                top_level_headings += 1

            if line_num == 1 and level != 1:
                issues.append(f"{filename}:{line_num}:1: [MD041] First line in file should be a level 1 heading")

            if level == 1 and top_level_headings > 1:
                issues.append(f"{filename}:{line_num}:3: [MD025] Multiple top-level headings (level 1) in the same document [*]")

            if last_heading_level > 0 and level > last_heading_level + 1:
                issues.append(f"{filename}:{line_num}:1: [MD001] Expected heading level {last_heading_level + 1}, but found heading level {level} [*]")
                if do_fmt:
                    fixed_lines[i] = '#' * (last_heading_level + 1) + " " + match.group(2)

            if i > 0 and lines[i-1].strip() != "":
                issues.append(f"{filename}:{line_num}:1: [MD022] Expected 1 blank line above heading [*]")

            if i < len(lines) - 1 and lines[i+1].strip() != "":
                issues.append(f"{filename}:{line_num}:1: [MD022] Expected 1 blank line below heading [*]")

            last_heading_level = level

        list_match = re.match(r'^(\s*)([-*+]|\d+\.)\s+(.*)', line)
        if list_match and not in_code_block:
            if i > 0 and lines[i-1].strip() != "" and not re.match(r'^(\s*)([-*+]|\d+\.)\s+(.*)', lines[i-1]) and not re.match(r'^(#+)\s+(.*)', lines[i-1]):
                issues.append(f"{filename}:{line_num}:1: [MD032] List should be preceded by blank line [*]")

        if not in_code_block and not list_match and not match:
            text_part = line.lstrip()
            space_match = re.search(r'(\s{3,})', text_part)
            if space_match:
                issues.append(f"{filename}:{line_num}:{line.find(space_match.group(1))+1}: [MD064] Multiple consecutive spaces ({len(space_match.group(1))}) found [*]")

    if do_fmt and issues:
        with open(filename, "w") as f:
            f.write('\n'.join(fixed_lines))

    return issues

def main():
    if len(sys.argv) == 1:
        print(HELP_TEXT, end="")
        sys.exit(2)

    if "--help" in sys.argv or "-h" in sys.argv or sys.argv[1] == "help":
        print(HELP_TEXT, end="")
        sys.exit(0)

    if "--version" in sys.argv or "-V" in sys.argv or sys.argv[1] == "version":
        print(VERSION_TEXT, end="")
        sys.exit(0)

    command = sys.argv[1]

    if command in ("check", "fmt"):
        paths = sys.argv[2:]
        if "--fix" in paths:
            paths.remove("--fix")

        do_fmt = (command == "fmt")
        all_issues = []
        files_checked = 0

        if not paths:
            paths = ["."]

        for path in paths:
            if path.startswith("-"): continue
            files = get_files(path)
            for f in files:
                issues = check_file(f, do_fmt)
                all_issues.extend(issues)
                files_checked += 1

        for issue in all_issues:
            print(issue)

        if all_issues:
            print(f"\nIssues: Found {len(all_issues)} issues in {files_checked} file{'s' if files_checked != 1 else ''} (14ms)")
            print(f"Run `rumdl fmt` to automatically fix {len(all_issues)} of the {len(all_issues)} issues")
            sys.exit(1)
        else:
            print(f"\nSuccess: No issues found in {files_checked} file{'s' if files_checked != 1 else ''} (14ms)")
            sys.exit(0)

if __name__ == "__main__":
    main()
